 static void RejectWrongImage(Fake service,Action apply,string message){var image=service.Rows.First(e=>e.LogicalName=="sdkmessageprocessingstepimage"&&service.Rows.Single(step=>step.Id==e.GetAttributeValue<EntityReference>("sdkmessageprocessingstepid").Id).GetAttributeValue<string>("name").EndsWith(" "+message,StringComparison.Ordinal));string original=image.GetAttributeValue<string>("messagepropertyname");Check(original=="Target",message+" expected native Target source");image["messagepropertyname"]="Id";int writes=service.Writes;bool denied=false;try{apply();}catch(InvalidOperationException){denied=true;}Check(denied&&service.Writes==writes,message+" wrong existing source rejected without mutation");image["messagepropertyname"]=original;}
 internal class Fake:IOrganizationService {
  public Guid Assembly=Guid.NewGuid();public bool WrongOrg,WrongAssemblyContent,NonStandard;public int Writes,Deletes,FailAfterWrites,Activations,Transactions;bool InTransaction;public bool FailDisable;public List<Entity> Rows=new List<Entity>();Guid CreateMessage=Guid.NewGuid(),UpdateMessage=Guid.NewGuid(),DeleteMessage=Guid.NewGuid(),UpsertMessage=Guid.NewGuid();Dictionary<string,Guid> Filters=new Dictionary<string,Guid>();
  public Entity Retrieve(string table,Guid id,ColumnSet cols){if(table=="systemuser"){var user=new Entity(table,id);user["applicationid"]=Guid.NewGuid();return user;}if(table=="pluginassembly"){var e=new Entity(table,Assembly);e["name"]="Oiac.Engage.SiteActivityLog";var local=typeof(Oiac.Engage.SiteActivityLog.SiteActivityLogNativeProvenancePlugin).Assembly;e["publickeytoken"]=BitConverter.ToString(local.GetName().GetPublicKeyToken()).Replace("-","").ToLowerInvariant();e["content"]=Convert.ToBase64String(WrongAssemblyContent?new byte[]{1,2,3}:File.ReadAllBytes(local.Location));e["version"]="1.0.0.0";e["isolationmode"]=new OptionSetValue(2);e["sourcetype"]=new OptionSetValue(0);return e;}var found=Rows.SingleOrDefault(e=>e.LogicalName==table&&e.Id==id);if(found==null)throw new FaultException<OrganizationServiceFault>(new OrganizationServiceFault{ErrorCode=-2147220969});return found;}
  public EntityCollection RetrieveMultiple(QueryBase query){var q=(QueryExpression)query;if(q.EntityName=="sdkmessage"){var name=(string)q.Criteria.Conditions[0].Values[0];var e=new Entity("sdkmessage",name=="Create"?CreateMessage:name=="Update"?UpdateMessage:name=="Delete"?DeleteMessage:UpsertMessage);e["name"]=name;return new EntityCollection(new[]{e});}if(q.EntityName=="sdkmessagefilter"){string key=string.Join("|",q.Criteria.Conditions.Select(c=>c.AttributeName+":"+Convert.ToString(c.Values[0])));if(!Filters.ContainsKey(key))Filters.Add(key,Guid.NewGuid());var e=new Entity(q.EntityName,Filters[key]);return new EntityCollection(new[]{e});}return new EntityCollection(Rows.Where(e=>e.LogicalName==q.EntityName&&q.Criteria.Conditions.All(c=>{object v;e.Attributes.TryGetValue(c.AttributeName,out v);if(v is EntityReference)v=((EntityReference)v).Id;return object.Equals(v,c.Values[0]);})).ToArray());}
  public Guid Create(Entity e){if(e.LogicalName=="sdkmessageprocessingstep"){e["statecode"]=new OptionSetValue(0);if(!e.Contains("statuscode"))e["statuscode"]=new OptionSetValue(1);Check(e.GetAttributeValue<OptionSetValue>("statuscode").Value==1,"SDK step Create defaults Enabled: disabled status2 rejected");}if(e.LogicalName=="sdkmessageprocessingstepimage"){var step=Rows.Single(row=>row.Id==e.GetAttributeValue<EntityReference>("sdkmessageprocessingstepid").Id);bool create=step.GetAttributeValue<EntityReference>("sdkmessageid").Id==CreateMessage;Check(e.GetAttributeValue<string>("messagepropertyname")== (create?"Id":"Target"),"SDK image source property rejected: expected "+(create?"Id":"Target"));Check(!create||e.GetAttributeValue<OptionSetValue>("imagetype").Value==1,"Create supports post image only");}Writes++;if(FailAfterWrites>0&&Writes>FailAfterWrites)throw new InvalidOperationException("simulated partial SDK registration failure");if(e.Id==Guid.Empty)e.Id=Guid.NewGuid();Rows.Add(e);return e.Id;}
  public void Delete(string table,Guid id){Check(table=="sdkmessageprocessingstep","only registration step deletion");Deletes++;Writes++;Rows.RemoveAll(e=>e.LogicalName==table&&e.Id==id);}
  public OrganizationResponse Execute(OrganizationRequest r){var transaction=r as ExecuteTransactionRequest;if(transaction!=null){Check(transaction.Requests.Count==2&&transaction.Requests[0] is CreateRequest&&transaction.Requests[1] is SetStateRequest,"disabled-step creation must be one atomic Create+SetState pair");var before=Rows.Select(e=>{var copy=new Entity(e.LogicalName,e.Id);foreach(var a in e.Attributes)copy[a.Key]=a.Value;return copy;}).ToList();Transactions++;InTransaction=true;var answer=new ExecuteTransactionResponse();var responses=new OrganizationResponseCollection();try{var create=(CreateRequest)transaction.Requests[0];var created=Create(create.Target);var first=new CreateResponse();first.Results["id"]=created;responses.Add(first);var disabledResponse=Execute(transaction.Requests[1]);responses.Add(disabledResponse);answer.Results["Responses"]=responses;return answer;}catch{Rows=before;throw;}finally{InTransaction=false;}}if(r is RetrieveEntityRequest){var metadata=new RetrieveEntityResponse();metadata.Results["EntityMetadata"]=new EntityMetadata{LogicalName="mss_activitylog",TableType=NonStandard?"Elastic":"Standard"};return metadata;}var state=r as SetStateRequest;if(state!=null){var row=Rows.Single(e=>e.LogicalName=="sdkmessageprocessingstep"&&e.Id==state.EntityMoniker.Id);if(state.State.Value==1){Check(InTransaction&&state.Status.Value==2,"new disabled step must be atomic");if(FailDisable)throw new InvalidOperationException("simulated disabled-state failure");}else{Check(row.GetAttributeValue<string>("name").StartsWith("OIAC History ")&&row.GetAttributeValue<string>("name").IndexOf("mss_activitylog",StringComparison.Ordinal)<0,"only native source/observer activation");Activations++;}row["statecode"]=state.State;row["statuscode"]=state.Status;Writes++;return new SetStateResponse();}Check(r is WhoAmIRequest,"only WhoAmI");var response=new WhoAmIResponse();response.Results["OrganizationId"]=WrongOrg?Guid.NewGuid():new Guid("3f613eb3-72ea-f011-aa23-6045bd003f09");return response;}
